function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var pairs := new List<(integer, integer)>;
  for var i := 0 to numbers.Length - 1 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
        pairs.Add((i, j));

  if pairs.Count = 0 then
    Result := False
  else
  begin
    var minIndex := pairs[0].Item1;
    var maxIndex := pairs[0].Item2;

    for var i := 1 to pairs.Count - 1 do
    begin
      if pairs[i].Item1 < minIndex then
        minIndex := pairs[i].Item1;
      if pairs[i].Item2 > maxIndex then
        maxIndex := pairs[i].Item2;
    end;

    Result := True;
  end;
end;

begin
end.




function SeparateParenGroups(parenString: string): array of string;
begin
  var groups := new List<string>;
  var currentGroup := '';
  var openParenCount := 0;

  for var i := 1 to parenString.Length do
  begin
    var currentChar := parenString[i];

    if currentChar = '(' then
      openParenCount += 1
    else if currentChar = ')' then
    begin
      if openParenCount > 0 then
      begin
        currentGroup += currentChar;
        openParenCount -= 1;
      end
      else
        currentGroup += currentChar;
    end
    else if currentChar = ' ' then
      continue
    else
    begin
      if openParenCount > 0 then
      begin
        currentGroup += currentChar;
        openParenCount -= 1;
      end
      else
        currentGroup += currentChar;
    end;

    if openParenCount = 0 then
    begin
      groups.Add(currentGroup);
      currentGroup := '';
    end;
  end;

  Result := groups.ToArray;
end;

begin
end.




