function ParseNestedParens(parenString: string): array of integer;
begin
  var levels := new List<integer>;
  var stack := new Stack<char>;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];
    if ch = '(' then
      stack.Push(ch)
    else if ch = ')' then
    begin
      if stack.Count > 0 then
        stack.Pop;
      if stack.Count = 0 then
        levels.Add(0)
      else
        levels.Add(stack.Peek() = '(' ? levels[levels.Count - 1] + 1 : 0);
    end;
  end;

  Result := levels.ToArray;
end;

begin
end.




