function MakePalindrome(str : string): string;
{ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> MakePalindrome('')
    ''
    >>> MakePalindrome('cat')
    'catac'
    >>> MakePalindrome('cata')
    'catac' }

```pascal
function IsPalindrome(s: string): boolean;
begin
  var i := 0;
  var j := s.Length - 1;
  while i < j do
  begin
    if s[i] <> s[j] then
    begin
      Result := False;
      exit;
    end;
    i += 1;
    j -= 1;
  end;
  Result := True;
end;

function MakePalindrome(str: string): string;
begin
  var s := str;
  var i := 0;
  var j := s.Length - 1;
  while i < j do
  begin
    if s[i] <> s[j] then
    begin
      var prefix := s.Substring(0, i);
      var suffix := s.Substring(j + 1);
      s := prefix + ReverseString(suffix);
      j := s.Length - 1;
    end;
    i += 1;
    j -= 1;
  end;
  Result := s;
end;

begin
end.



