function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to brackets.Length do
  begin
    var bracket := brackets[i];

    if bracket = '<' then
      stack.Push(bracket)
    else
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      var top := stack.Peek;

      if top = '<' then
        stack.Pop
      else
      begin
        stack.Pop;
        stack.Push(bracket);
      end;
    end;
  end;

  Result := stack.Count = 0;
end;

begin
end.




