      freq[num] := 1;
  var maxVal := 0;
  var maxFreq := 0;
  foreach var kv in freq do
    if kv.Value > maxFreq then
    begin
      maxVal := kv.Key;
      maxFreq := kv.Value;
    end;
  if maxFreq < maxVal then
    Result := -1
  else
    Result := maxVal;
end;

