  var sorted := new List<integer>;
  var remaining := new List<integer>;

  foreach var num in lst do
    if num = lst.Min then
      sorted.Add(num)
    else
      remaining.Add(num);

  var resultList := new List<integer>;
  while remaining.Count > 0 do
  begin
    if sorted.Count > 0 then
    begin
      if sorted.Count > 0 then
        resultList.Add(sorted.Min);
      sorted.RemoveAt(0);
    end
    else
    begin
      if remaining.Count > 0 then
        resultList.Add(remaining.Min);
      remaining.RemoveAt(0);
    end;
  end;

  Result := resultList.ToArray;
end;

begin
end.




