function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n];
  for var i := 0 to n - 1 do
    dp[i] := 1;
  for var i := 1 to n - 1 do
    if arr[i] = arr[i - 1] then
      dp[i] := 2
    else
      dp[i] := 1;
  for var i := 3 to n do
    for var j := 0 to n - i do
    begin
      if arr[j + 1] = arr[j + 2] then
        dp[i] := Min(dp[i], dp[j + 1] + 1)
      else
        dp[i] := Min(dp[i], dp[j + 1] + 2);
    end;
  Result := dp[n];
end;

begin
end.




