function Encode(message: string): string;
begin
  var encoded := '';
  foreach var ch in message do
  begin
    if ch.IsLetter then
    begin
      var encodedChar := if ch.ToLower = 'a' then 'B'
        else if ch.ToLower = 'e' then 'D'
        else if ch.ToLower = 'i' then 'F'
        else if ch.ToLower = 'o' then 'H'
        else if ch.ToLower = 'u' then 'J'
        else if ch.ToLower = 'y' then 'L'
        else if ch.ToLower = 'z' then 'N'
        else ch.ToUpper;
      encoded += if ch.IsLower then encodedChar.ToLower
        else encodedChar.ToUpper;
    end
    else
      encoded += ' ';
  end;
  Result := encoded;
end;

