function Skjkasdkd(lst: array of integer): integer;
begin
  var primeList := new List<integer>;
  var nonPrimeList := new List<integer>;

  foreach var num in lst do
  begin
    if num = 0 then
    begin
      nonPrimeList.Add(num);
      continue;
    end;

    var isPrime := True;
    for var i := 2 to Round(Sqrt(num)) do
      if num mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primeList.Add(num);
    else
      nonPrimeList.Add(num);
  end;

  var maxPrime := 0;
  foreach var num in primeList do
    if num > maxPrime then
      maxPrime := num;

  var sumOfDigits := 0;
  while maxPrime > 0 do
  begin
    sumOfDigits += (maxPrime mod 10);
    maxPrime := maxPrime div 10;
  end;

  Result := sumOfDigits;
end;

begin
end.




