function Histogram(test: string): Dictionary<string, integer>;
begin
  var histogram := new Dictionary<string, integer>;
  var words := test.Split(' ');

  foreach var word in words do
  begin
    if histogram.ContainsKey(word) then
      histogram[word] += 1
    else
      histogram[word] := 1;
  end;

  var maxCount := 0;
  foreach var kv in histogram do
    if kv.Value > maxCount then
      maxCount := kv.Value;

  var maxCountWords := new List<string>;
  foreach var kv in histogram do
    if kv.Value = maxCount then
      maxCountWords.Add(kv.Key);

  Result := new Dictionary<string, integer>;
  foreach var word in maxCountWords do
    Result[word] := maxCount;
end;

begin
end.




