function SortArray(arr: array of integer): array of integer;
begin
  var sorted := new List<integer>;
  var counts := new List<(integer, integer)>;

  foreach var num in arr do
  begin
    var count := 0;
    var n := num;

    while n > 0 do
    begin
      if n and 1 = 1 then
        count += 1;
      n := n shr 1;
    end;

    counts.Add((count, num));
  end;

  counts.Sort((x, y) ->
  begin
    if x.Item1 = y.Item1 then
      Result := x.Item2.CompareTo(y.Item2)
    else
      Result := x.Item1.CompareTo(y.Item1);
  end);

  foreach var (count, num) in counts do
    sorted.Add(num);

  Result := sorted.ToArray;
end;

begin
end.




