  var n := word.Length;
  var i := n - 1;
  var closestVowel := '';

  while i > 0 do
  begin
    if vowels.Contains(word[i]) then
    begin
      if (i = 1) or (not vowels.Contains(word[i-1])) then
      begin
        closestVowel := word[i];
        break;
      end;
    end;
    i -= 1;
  end;

  Result := closestVowel;
end;

