function Maximum(arr: array of integer; k: integer): array of integer;
begin
  var res := new List<integer>;
  var temp := new List<integer>;
  var maxVal := integer.MinValue;
  var maxCount := 0;

  foreach var num in arr do
  begin
    if num > maxVal then
    begin
      maxVal := num;
      maxCount := 1;
    end
    else if num = maxVal then
      maxCount += 1;
  end;

  if maxCount = 0 then
  begin
    Result := temp.ToArray;
    exit;
  end;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] = maxVal then
    begin
      temp.Add(arr[i]);
      if temp.Count = k then
        break;
    end;
  end;

  res.AddRange(temp);

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] = maxVal then
    begin
      if res.Count = 0 then
        res.Add(arr[i])
      else
      begin
        var j := res.Count - 1;
        while (j >= 0) and (arr[i] > arr[res[j]]) do
        begin
          res[j + 1] := arr[i];
          j -= 1;
        end;
      end;
    end;
  end;

  Result := res.ToArray;
end;

begin
end.




