  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var prod := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    if num < 0 then
    begin
      sign := -1;
      num := -num;
    end;

    prod *= num;
    sum += num;
  end;

  Result := sign * Abs(prod) * sum;
end;

