end.




function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var N := grid.Length;
  var res := new integer[k];
  var directions := [|(0, 1), (1, 0), (0, -1), (-1, 0)|];
  var visited := new boolean[N * N];
  var dist := new integer[N * N];
  for var i := 0 to N - 1 do
    for var j := 0 to N - 1 do
      dist[i * N + j] := grid[i][j];
  var minDist := dist.Min;
  var minIndex := dist.IndexOf(minDist);
  res[0] := grid[minIndex div N][minIndex mod N];
  var current := res[0];
  var count := 1;
  while count < k do
  begin
    var neighbors := new integer[4];
    var index := 0;
    for var i := 0 to 3 do
    begin
      var d := directions[i];
      var x := current div N + d.Item1;
      var y := current mod N + d.Item2;
      if (x >= 0) and (x < N) and (y >= 0) and (y < N) and not visited[x * N + y] then
      begin
        neighbors[index] := grid[x][y];
        index += 1;
      end;
    end;
    var minDist := dist.Min;
    var minIndex := dist.IndexOf(minDist);
    res[count] := grid[minIndex div N][minIndex mod N];
    visited[minIndex] := true;
    current := res[count];
    count += 1;
  end;
  Result := res;
end;

begin
end.




function Tri(n: integer): array of real;
begin
  var res := new List<real>;
  if n = 0 then
  begin
    Result := res.ToArray;
    exit;
  end;

  if n = 1 then
  begin
    res.Add(3);
    Result := res.ToArray;
    exit;
  end;

  if n = 2 then
  begin
    res.Add(3);
    res.Add(2);
    Result := res.ToArray;
    exit;
  end;

  res.Add(3);
  res.Add(2);
  res.Add(1);

  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      res.Add(res[i - 1] + res[i - 2] + res[i - 3])
    else
      res.Add(res[i - 1] + res[i - 2] + res[i - 3] + 1);
  end;

  Result := res.ToArray;
end;

begin
end.




function Digits(n: integer): integer;
begin
  var product := 1;
  var num := n;
  while num > 0 do
  begin
    var digit := num mod 10;
    if digit mod 2 <> 0 then
      product *= digit;
    num := num div 10;
  end;
  if product = 1 then
    Result := 0
  else
    Result := product;
end;

