end.




function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      if stack.Peek = '[' then
        stack.Pop
      else
      begin
        Result := False;
        exit;
      end;
    end;
  end;
  Result := stack.Count = 0;
end;

begin
end.




