    else if bStr.EndsWith(',') then
      bStr := bStr.Substring(0, bStr.Length - 1);
    if aStr = bStr then
      Result := nil
    else if aStr > bStr then
      Result := aStr
    else
      Result := bStr;
  end
  else
  begin
    if a is integer then
    begin
      if b is integer then
        Result := Max(a, b)
      else
        Result := a;
    end
    else
    begin
      if b is integer then
        Result := Max(b, a)
      else
        Result := b;
    end;
  end;
end;

