function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

