function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    if op[i-1] = '+' then
      res := res + operand[i]
    else if op[i-1] = '-' then
      res := res - operand[i]
    else if op[i-1] = '*' then
      res := res * operand[i]
    else if op[i-1] = '//' then
      res := res div operand[i]
    else if op[i-1] = '**' then
      res := res := Power(res, operand[i]);
  end;
  Result := res;
end;

begin
end.




function Solve(s: string): string;
begin
  var res := new List<char>;
  var flag := False;
  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      if flag then
        res.Add(char.ToUpper(ch))
      else
        res.Add(char.ToLower(ch));
      flag := not flag;
    end
    else
      res.Add(ch);
  end;
  if res.All(ch -> ch.IsLetter) then
    Result := res.Reverse.ToString
  else
    Result := res.ToString;
end;

begin
end.




